167	{
168	    try
169	    {
170	        return mainImpl(argc, argv);
171	    }
172	    catch (const Poco::Exception & e)
173	    {
174	        std::cerr << e.what() << ", " << e.message() << std::endl;
175	        return 1;
176	    }
177	}
